import java.util.*;

public class Gestionnaire {
    private final List<Tache> taches = new ArrayList<>();
    private int prochainId = 1;

    String traiter(Commande commande) {
        return switch (commande) {
            case Ajouter(String titre) -> {
                Tache t = new Tache(prochainId++, titre, false);
                taches.add(t);
                yield "Ajoutee : " + titre;
            }
            case Terminer(int id) -> {
                for (int i = 0; i < taches.size(); i++) {
                    if (taches.get(i).id() == id) {
                        taches.set(i, taches.get(i).terminer());
                        yield "Terminee : tache " + id;
                    }
                }
                yield "Introuvable : tache " + id;
            }
            case Lister() -> "liste";
        };
    }
}
